 ('siege: a moose that only pushes', _sg("_2battle"), '            t.x = clamp(nx, 8, VIEW_W - 8)', '            pass', "Moose's hit knocks", SIEGE),
 ('siege: a moose pulls', _sg("_2battle"), '        nx = t.x + KNOCKBACK * forward(u.side)', '        nx = t.x - KNOCKBACK * forward(u.side)', "Moose's hit knocks", SIEGE),
 ('siege: a smooth hedgehog', _sg("_2battle"), '        hurt(u, THORNS * t.power)', '        pass', "Hedgehog hurts", SIEGE),
 ('siege: dams anywhere', _sg("_1rules"), '        return on_a_bridge(x, y)', '        return True', "Beaver Dam goes only", SIEGE),
 ('siege: dams stop nobody', _sg("Unit"), 'waypoint(self.x, self.y, t.x, t.y, self.side)', 'waypoint(self.x, self.y, t.x, t.y)', "Beaver Dam goes only", SIEGE),
 ('siege: your own dam stops you', _sg("_1rules"), '    return any(d.side != side and abs(d.y - LANES[lane]) <= BRIDGE', '    return any(abs(d.y - LANES[lane]) <= BRIDGE', "Beaver Dam goes only", SIEGE),
 ('siege: a cold campfire', _sg("Campfire"), '            u.hp = min(u.max_hp, u.hp + CAMPFIRE_HEAL * self.power)', '            pass', "Campfire warms", SIEGE),
 ('siege: campfires burn kids', _sg("Campfire"), '        elif type(u).__name__ in SNOWY:', '        else:', "Campfire warms", SIEGE),
 ('siege: campfires never go out', _sg("Campfire"), 'self.hp -= self.max_hp / self.life\n', '', "Campfire warms", SIEGE),
 ('siege: fireworks hit your own', _sg("Fireworks"), '    for o in enemies_of(self.side):', '    for o in instances("Unit") + instances("Building"):', "Fireworks burst all over", SIEGE),
 ('siege: one firework', _sg("Fireworks"), 'self.t // FIREWORKS_EVERY <= FIREWORKS_BURSTS', 'self.t // FIREWORKS_EVERY <= 1', "Fireworks burst all over", SIEGE),
 ('siege: one squirrel', _sg("_1rules"), '"object": "Squirrel", "count": 2,', '"object": "Squirrel", "count": 1,', "Squirrel Thieves come two", SIEGE),
 ('siege: squirrels steal nothing', _sg("_2battle"), '        global_vars.energy[t.side] -= 1\n', '', "Squirrel Thieves come two", SIEGE),
 ('siege: bursts not mirrored', _sg("_4cards"), 'd * math.cos(a) * (-1 if fw.puppet else 1)', 'd * math.cos(a)', "same fireworks bursts", SIEGE),
